using Godot;
using System;
using System.Globalization;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioOptionalWorkflowOperations:RefCounted
{
    private const string Config="user://audio_workspace/optional_tools.cfg";
    private static T Field<T>(GodotObject o,string key) where T:GodotObject=>(T)o.Get(key).AsGodotObject();
    private static Settings Dict(GodotObject o,string key)=>o.Get(key).AsGodotDictionary();
    private static Variant Get(Settings d,string key,Variant fallback=default)=>d.TryGetValue(key,out var v)?v:fallback;
    private static string S(Settings d,string key,string fallback="")=>Get(d,key,fallback).AsString();
    private static GodotObject Workspace(Node o)=>o.GetParent();
    private static void Notice(GodotObject w,string message)=>w.Call("notice",message);
    private static Button Button(GodotObject w,Node parent,string label,System.Action action)=>w.Call("_button",parent,label,Callable.From(action),"").As<Button>();
    private static void Label(GodotObject w,Node parent,string text)=>w.Call("_label",parent,text);
    private static Settings Window(GodotObject w,string title,Vector2I size)=>w.Call("_window",title,size).AsGodotDictionary();
    private static void Request(Node o,string kind,Func<RefCounted,Variant> work)=>Field<Node>(o,"jobs").Call("request",kind,Callable.From(work),0,true);
    public string remember(Node o,string kind,Settings context){var contexts=Dict(o,"contexts");foreach(var token in contexts.Keys)if(S(contexts[token].AsGodotDictionary(),"kind")==kind)contexts.Remove(token);using var crypto=new Crypto();string id=Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant();context["kind"]=kind;contexts[id]=context;return id;}
    public void ready(Node o)
    {
        var jobs=Field<Node>(o,"jobs");o.AddChild(jobs);jobs.Connect("completed",new Callable(o,"_completed"));jobs.Connect("progress_changed",Callable.From<double,string>((value,message)=>{var w=Workspace(o);Field<Godot.Range>(w,"progress").Value=value*100;Field<Godot.Label>(w,"status").Text=message;}));o.Call("_initialize_provider");using var config=new ConfigFile();if(config.Load(Config)==Error.Ok){var settings=Dict(o,"settings");foreach(var key in settings.Keys)settings[key]=config.GetValue("tools",key.AsString(),settings[key]).AsString();}
    }
    public Settings context(Node o){var w=Workspace(o);var session=Field<RefCounted>(w,"session");var document=session.Get("document").AsGodotObject();using var signatures=new AudioRecordingPrepareOperations();return new Settings{["owner"]=session,["document"]=document,["revision"]=session.Get("revision"),["signature"]=signatures.signature(document),["time"]=Field<GodotObject>(w,"playback").Get("position"),["track"]=session.Get("selected_track")};}
    public bool current(Node o,Settings context)
    {
        var w=Workspace(o);var session=Field<RefCounted>(w,"session");using var signatures=new AudioRecordingPrepareOperations();return session==Get(context,"owner").AsGodotObject()&&session.Get("document").AsGodotObject()==Get(context,"document").AsGodotObject()&&session.Get("revision").AsInt64()==Get(context,"revision").AsInt64()&&signatures.signature(session.Get("document").AsGodotObject())==S(context,"signature")&&!Field<GodotObject>(w,"recorder").Get("recording").AsBool()&&!w.Get("_record_busy").AsBool()&&session.Get("_before").AsGodotObject()==null&&!Field<GodotObject>(w,"automation_recording").Get("active").AsBool()&&!Field<GodotObject>(w,"automation_recording").Call("has_pending").AsBool();
    }
    public void transcribe(Node o)
    {
        var w=Workspace(o);var session=Field<RefCounted>(w,"session");var clip=session.Call("primary_clip").AsGodotObject();if(clip==null){Notice(w,"Select one dialogue clip to transcribe.");return;}if(!session.Call("can_edit",clip.Get("id")).AsBool()||Field<GodotObject>(w,"recorder").Get("recording").AsBool()||w.Get("_record_busy").AsBool()||session.Get("_before").AsGodotObject()!=null){Notice(w,"Finish recording/editing and select an unlocked clip first.");return;}var settings=Dict(o,"settings");if(S(settings,"whisper").Length==0||S(settings,"model").Length==0){configure(o);return;}var source=context(o);source["clip_id"]=clip.Get("id");string token=remember(o,"transcribe",source),id=clip.Get("id").AsString(),executable=S(settings,"whisper"),model=S(settings,"model");var snapshot=session.Get("document").AsGodotObject().Call("snapshot").As<RefCounted>();Request(o,"transcribe",job=>{using var transcription=new AudioTranscriptionOperations();var result=transcription.run(snapshot,id,executable,model,job);result["token"]=token;return result;});Field<Godot.Label>(w,"status").Text="Preparing selected clip for local transcription\u2026";
    }
    public void review_saved_transcript(Node o)
    {
        var w=Workspace(o);var session=Field<RefCounted>(w,"session");var actor=session.Call("primary_actor").AsGodotObject();var clip=session.Call("primary_clip").AsGodotObject();var transcript=actor!=null?Get(actor.Get("values").AsGodotDictionary(),"transcript"):default;if(actor==null||clip==null||transcript.VariantType!=Variant.Type.Dictionary){Notice(w,"The selected clip has no saved transcript.");return;}var source=context(o);source["clip_id"]=clip.Get("id");if(!current(o,source)){Notice(w,"Finish the current edit/recording before reviewing a transcript.");return;}review(o,source,transcript.AsGodotDictionary().Duplicate(true));
    }
    public void completed(Node o,string kind,Variant raw)
    {
        if(raw.VariantType!=Variant.Type.Dictionary)return;var result=raw.AsGodotDictionary();var w=Workspace(o);if(kind=="vault"){Notice(w,Get(result,"success",false).AsBool()?"Credential operation completed. No key is stored in the composition.":S(result,"error","Credential operation failed."));return;}string token=S(result,"token");var contexts=Dict(o,"contexts");var source=Get(contexts,token,new Settings()).AsGodotDictionary();contexts.Remove(token);if(source.Count==0||!current(o,source)){Field<Godot.Label>(w,"status").Text="Optional audio job discarded because its original composition changed.";return;}if(S(result,"error").Length>0){Notice(w,S(result,"error"));return;}if(kind=="transcribe"){review(o,source,result);return;}if(kind!="speech")return;
        var dialog=Window(w,"Review generated speech",new Vector2I(560,280));var host=dialog["host"].As<Node>();var window=dialog["window"].As<Window>();var stream=result["stream"].As<AudioStream>();Label(w,host,"Review before inserting. This result stays local. Insert preserves the generated-audio provenance and supports Undo.");Button(w,host,"Audition",()=>{var player=Field<AudioStreamPlayer>(w,"preview_player");player.Stream=stream;player.Play();});Button(w,host,"Insert at original playhead · one Undo",()=>{if(!current(o,source)){Notice(w,"The composition changed. Generate again in the intended composition.");return;}var session=Field<RefCounted>(w,"session");var document=session.Get("document").AsGodotObject();var track=document.Call("track_for_id",S(source,"track")).AsGodotDictionary();if(track.Count==0||Get(track,"locked",false).AsBool()){Notice(w,"The original destination track is unavailable or locked.");return;}session.Call("begin","Insert generated speech");using var edits=new AudioEditSessionOperations();var clip=edits.insert_source(session,stream,source["time"].AsDouble(),S(source,"track"),"Generated speech").AsGodotObject();if(clip==null){session.Call("cancel");Notice(w,"The original destination track cannot accept this audio.");return;}document.Call("actor_for_clip",clip.Get("id")).AsGodotObject().Get("values").AsGodotDictionary()[new StringName("provider_origin")]=result["metadata"].AsGodotDictionary().Duplicate(true);session.Call("commit");window.QueueFree();});
    }
    public void review(Node o,Settings source,Settings result)
    {
        var w=Workspace(o);var dialog=Window(w,"Review local transcript",new Vector2I(780,600));var host=dialog["host"].As<Node>();var window=dialog["window"].As<Window>();Label(w,host,"Recognition can be wrong. Edit the text before saving; source audio is untouched. Segment timing follows the rendered clip, including its playback transforms.");var text=new TextEdit{Text=S(result,"text"),SizeFlagsVertical=Control.SizeFlags.ExpandFill};host.AddChild(text);var rows=new ItemList{CustomMinimumSize=new Vector2(0,140)};host.AddChild(rows);var segments=result["segments"].AsGodotArray();foreach(var raw in segments){var segment=raw.AsGodotDictionary();rows.AddItem(segment["start"].AsDouble().ToString("F2",CultureInfo.InvariantCulture)+"–"+segment["end"].AsDouble().ToString("F2",CultureInfo.InvariantCulture)+"  "+S(segment,"text"));}rows.ItemActivated+=index=>{if(current(o,source)){var clip=source["document"].AsGodotObject().Call("clip_for_id",S(source,"clip_id")).AsGodotObject();Field<GodotObject>(w,"playback").Call("seek",clip.Get("start_time").AsDouble()+segments[(int)index].AsGodotDictionary()["start"].AsDouble());}};var markers=new CheckBox{Text="Also add segment cue markers (original recognized text)"};host.AddChild(markers);Button(w,host,"Save reviewed transcript · one Undo",()=>{if(!current(o,source)){Notice(w,"The composition changed. Transcribe again to preserve timing.");return;}using var transcription=new AudioTranscriptionOperations();string error=transcription.apply(Field<RefCounted>(w,"session"),S(source,"clip_id"),result,text.Text,markers.ButtonPressed);if(error.Length>0)Notice(w,error);else window.QueueFree();});
    }
    public void cancel(Node o){Field<Node>(o,"jobs").Call("cancel_all");Dict(o,"contexts").Clear();}
